steps.checkScript:
need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need hello.sh
out=$(timeout 5 sh hello.sh 2>&1)
[ "$out" = "Hello World" ] || { echo "sh hello.sh soll genau 'Hello World' ausgeben, war: $out"; exit 1; }
echo "Läuft!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need hello.sh
head -n1 hello.sh | grep -Eq '^#!/(usr/)?bin/(env )?(ba)?sh' || { echo "Die erste Zeile von hello.sh muss die Shebang-Zeile #!/bin/sh sein."; exit 1; }
[ -x hello.sh ] || { echo "hello.sh ist noch nicht ausführbar (chmod)."; exit 1; }
out=$(timeout 5 ./hello.sh 2>&1)
[ "$out" = "Hello World" ] || { echo "./hello.sh soll 'Hello World' ausgeben, war: $out"; exit 1; }
echo "Direkt startbar!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need path.txt
grep -q '/usr/bin' path.txt || { echo "In path.txt steht nicht der Inhalt von \$PATH."; exit 1; }
echo "Genau – der aktuelle Ordner ist nicht im PATH, deshalb ./"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need args.sh
a=w$RANDOM; b=x$RANDOM; c=y$RANDOM
out=$(timeout 5 bash args.sh "$a" "$b" "$c" z 2>&1)
l() { echo "$out" | sed -n "${1}p"; }
[ "$(l 1)" = 4 ] || { echo "Zeile 1 soll die Anzahl der Argumente (\$#) sein. Ausgabe: $out"; exit 1; }
l 2 | grep -q 'args.sh' || { echo "Zeile 2 soll den Skriptnamen (\$0) zeigen. Ausgabe: $out"; exit 1; }
[ "$(l 3)" = "$a" ] && [ "$(l 4)" = "$b" ] && [ "$(l 5)" = "$c" ] || { echo "Zeilen 3–5 sollen \$1, \$2 und \$3 sein. Ausgabe: $out"; exit 1; }
echo "Argumente verstanden!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need alle.sh
out=$(timeout 5 bash alle.sh eins "zwei drei" vier 2>&1)
want=$(printf 'eins\nzwei drei\nvier')
[ "$out" = "$want" ] || { echo "Erwartet wurde:"; echo "$want"; echo "Ausgabe war:"; echo "$out"; echo "(Tipp: \"\$@\" in Anführungszeichen)"; exit 1; }
echo "Perfekt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need datum.txt
grep -Eq '^Das aktuelle Datum ist .*[0-9]{4}' datum.txt || { echo "datum.txt soll 'Das aktuelle Datum ist <Ausgabe von date>' enthalten."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need woche.txt
want="Heute $(date -I) in einer Woche ist $(date --date='+1 week' -I)"
[ "$(cat woche.txt)" = "$want" ] || { echo "woche.txt soll genau so aussehen: $want"; exit 1; }
echo "Stimmt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need anzahl.txt
want="Es sind $(ls /etc | wc -l) Einträge im dir /etc"
[ "$(cat anzahl.txt)" = "$want" ] || { echo "anzahl.txt soll genau so aussehen: $want"; exit 1; }
echo "Gezählt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need liste.txt
[ "$(cat liste.txt)" = "file1 file2 file3" ] || { echo "liste.txt soll genau 'file1 file2 file3' enthalten."; exit 1; }
echo "Genau – aus Newlines werden Leerzeichen."

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need let.txt
[ "$(tr -d '[:space:]' < let.txt)" = 9 ] || { echo "In let.txt soll 9 stehen."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need expr.txt
[ "$(tr -d '[:space:]' < expr.txt)" = 6 ] || { echo "In expr.txt soll 6 stehen."; exit 1; }
echo "Richtig maskiert!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need potenz.txt
[ "$(tr -d '[:space:]' < potenz.txt)" = 1024 ] || { echo "In potenz.txt soll 1024 stehen."; exit 1; }
echo "Stimmt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need rest.txt
[ "$(tr -d '[:space:]' < rest.txt)" = 2 ] || { echo "In rest.txt soll der Rest von 17 / 5 stehen."; exit 1; }
echo "Genau – der Modulo-Operator %."

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need status.txt
[ "$(tr -d '[:space:]' < status.txt)" = 1 ] || { echo "In status.txt soll der Exit-Status des Vergleichs stehen (die Strings sind ungleich)."; exit 1; }
echo "Richtig – 1 heißt false."

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need ja.txt
[ "$(cat ja.txt)" = "Yes, that's true." ] || { echo "ja.txt soll genau: Yes, that's true. enthalten."; exit 1; }
echo "Passt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need nein.txt
[ "$(cat nein.txt)" = "No, that's false." ] || { echo "nein.txt soll genau: No, that's false. enthalten."; exit 1; }
echo "Passt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need dir.txt
[ "$(tr -d '[:space:]' < dir.txt)" = 1 ] || { echo "In dir.txt soll der Exit-Status von test -d /etc/gibtsnicht stehen."; exit 1; }
echo "Genau!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need gross.sh
timeout 5 bash gross.sh 150 2>&1 | grep -q "Hey that's a large number." || { echo "'./gross.sh 150' soll Hey that's a large number. ausgeben."; exit 1; }
[ -z "$(timeout 5 bash gross.sh 50 2>&1)" ] || { echo "'./gross.sh 50' soll nichts ausgeben."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need param3.sh
[ "$(timeout 5 bash param3.sh a b drei 2>&1)" = "Parameter #3 is drei" ] || { echo "'./param3.sh a b drei' soll 'Parameter #3 is drei' ausgeben."; exit 1; }
[ "$(timeout 5 bash param3.sh a b 2>&1)" = "Parameter #3 fehlt" ] || { echo "'./param3.sh a b' soll 'Parameter #3 fehlt' ausgeben."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need lesbar.sh
echo x > "$t/voll"; : > "$t/leer"
[ "$(timeout 5 bash lesbar.sh "$t/voll" 2>&1)" = OK ] || { echo "Bei einer Datei mit Inhalt soll OK kommen."; exit 1; }
[ "$(timeout 5 bash lesbar.sh "$t/leer" 2>&1)" = "NICHT OK" ] || { echo "Bei einer leeren Datei soll NICHT OK kommen."; exit 1; }
[ "$(timeout 5 bash lesbar.sh "$t/fehlt" 2>&1)" = "NICHT OK" ] || { echo "Bei einer fehlenden Datei soll NICHT OK kommen."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need vergleich.sh
[ "$(timeout 5 bash vergleich.sh 42 10 2>&1)" = "42 > 10" ] || { echo "'./vergleich.sh 42 10' soll '42 > 10' ausgeben."; exit 1; }
[ "$(timeout 5 bash vergleich.sh 3 10 2>&1)" = "3 <= 10" ] || { echo "'./vergleich.sh 3 10' soll '3 <= 10' ausgeben."; exit 1; }
grep -q '((' vergleich.sh || { echo "Verwende (( )) für den Vergleich."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need params.sh
out=$(timeout 5 bash params.sh 1 zwei 3 2>&1)
[ "$out" = "$(printf 'Param: 1\nParam: zwei\nParam: 3')" ] || { echo "'./params.sh 1 zwei 3' soll drei Zeilen 'Param: …' ausgeben. Ausgabe: $out"; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need hallo.txt
[ "$(cat hallo.txt)" = "$(for x in $(seq 1 10); do echo "hallo $x"; done)" ] || { echo "hallo.txt soll die Zeilen hallo 1 bis hallo 10 enthalten."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need conf.txt
[ "$(cat conf.txt)" = "$(cd /etc && printf '%s\n' *.conf)" ] || { echo "conf.txt soll die Namen aller *.conf-Dateien in /etc enthalten (einer pro Zeile, ohne Pfad)."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need countdown.txt
[ "$(cat countdown.txt)" = "$(seq 10 -1 1)" ] || { echo "countdown.txt soll die Zahlen 10 bis 1 enthalten."; exit 1; }
echo "Liftoff!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need potenzen.txt
[ "$(cat potenzen.txt)" = "$(printf '%s\n' 1 2 4 8 16 32 64 128 256 512)" ] || { echo "potenzen.txt soll 1, 2, 4, … 512 enthalten (eine Zahl pro Zeile)."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need ssh1.txt
grep -Eq '^[[:space:]]*ssh[[:space:]]+admin@10\.10\.10\.11[[:space:]]*$' ssh1.txt || { echo "Der Befehl in ssh1.txt stimmt noch nicht."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need ssh2.txt
grep -Eq "^[[:space:]]*ssh[[:space:]]+root@123\.123\.123\.123[[:space:]]+['\"]uname -a['\"][[:space:]]*$" ssh2.txt || { echo "Der Befehl in ssh2.txt stimmt noch nicht."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need scp1.txt
grep -Eq '^[[:space:]]*scp[[:space:]]+bericht\.txt[[:space:]]+admin@10\.10\.10\.11:/home/admin/backup(/|/bericht\.txt)?[[:space:]]*$' scp1.txt || { echo "Der Befehl in scp1.txt stimmt noch nicht (Ziel als absoluter Pfad)."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need scp2.txt
grep -Eq '^[[:space:]]*scp[[:space:]]+admin@10\.10\.10\.11:/var/log/syslog[[:space:]]+(\./)?syslog\.txt[[:space:]]*$' scp2.txt || { echo "Der Befehl in scp2.txt stimmt noch nicht."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need scp3.txt
grep -Eq '^[[:space:]]*scp[[:space:]]+(-[a-zA-Z]*r[a-zA-Z]*[[:space:]]+)projects/?[[:space:]]+admin@10\.10\.10\.11:/home/admin/backup/?[[:space:]]*$' scp3.txt || { echo "Der Befehl in scp3.txt stimmt noch nicht – denk an die Option für rekursives Kopieren."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need hello_fn.sh
grep -Eq '^[[:space:]]*(function[[:space:]]+)?myfunction[[:space:]]*\(\)' hello_fn.sh || { echo "In hello_fn.sh fehlt die Funktion myfunction()."; exit 1; }
[ "$(timeout 5 bash hello_fn.sh 2>&1)" = "$(printf 'Hello World\nHello World')" ] || { echo "hello_fn.sh soll zweimal Hello World ausgeben."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need functions.sh
a=a$RANDOM; b=b$RANDOM
out=$(timeout 5 bash functions.sh $a $b 2>&1)
[ "$out" = "$(printf '%s\n' $a $b 'Guten Morgen' 'Liebe 3AHITS' $a $b)" ] || { echo "'./functions.sh $a $b' soll ausgeben: $a, $b, Guten Morgen, Liebe 3AHITS, $a, $b. Ausgabe:"; echo "$out"; exit 1; }
echo "Richtig – die Parameter sind lokal."

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need gross_fn.sh
grep -q 'return' gross_fn.sh || { echo "Verwende return in der Funktion."; exit 1; }
grep -Eq 'ist_gross[[:space:]]*\(\)' gross_fn.sh || { echo "Es fehlt die Funktion ist_gross()."; exit 1; }
[ "$(timeout 5 bash gross_fn.sh 500 2>&1)" = "groß" ] || { echo "'./gross_fn.sh 500' soll groß ausgeben."; exit 1; }
[ "$(timeout 5 bash gross_fn.sh 7 2>&1)" = "klein" ] || { echo "'./gross_fn.sh 7' soll klein ausgeben."; exit 1; }
echo "Richtig!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need quadrat.sh
grep -Eq '\$\([[:space:]]*quadrat' quadrat.sh || { echo "Hole das Ergebnis mit \$(quadrat …)."; exit 1; }
n=$((RANDOM%300+20))
[ "$(timeout 5 bash quadrat.sh $n 2>&1)" = "Quadrat: $((n*n))" ] || { echo "'./quadrat.sh $n' soll 'Quadrat: $((n*n))' ausgeben."; exit 1; }
echo "Richtig – größer als 255 geht nur so!"
